<!doctype html><html lang="id"><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;background:#050505;color:#fff;text-align:center;padding:100px 80px}.card{border:2px solid #ff4500;padding:70px 50px}.eyebrow{color:#ff4500;font-size:12px;letter-spacing:4px}.mark{margin:30px auto 20px;width:52px;height:52px;line-height:52px;background:#ff4500;font-weight:bold;font-size:24px}.title{font-family:DejaVu Serif,serif;font-size:34px;margin:20px}.name{font-family:DejaVu Serif,serif;font-size:30px;margin:24px}.exam{font-size:20px}.score{font-size:28px;color:#ff4500;margin:25px}.meta{border-top:1px solid #292929;padding-top:18px;color:#aaa;font-size:12px}</style></head><body><div class="card"><div class="eyebrow">CBT.EDUKA / CERTIFICATE</div><div class="mark">C</div><div class="title">Sertifikat Kelulusan</div><div>Diberikan kepada</div><div class="name">{{ $certificate->student->name }}</div><div>atas keberhasilan menyelesaikan ujian</div><div class="exam">{{ $certificate->result->exam->name }}</div><div class="score">{{ number_format((float) $certificate->result->score, 1) }} / 100</div><div class="meta">Nomor: {{ $certificate->certificate_number }}<br>Diterbitkan: {{ $certificate->issued_at->format('d F Y') }}</div></div></body></html>
